import re
import time
from abc import ABC, abstractmethod

from taf.hw.optical_switch.devices.tcp import TCPOpticalSwitch
from taf.hw.optical_switch.exceptions import (
    InvalidInput,
    OpticalSwitchResponseError,
    TooManyRetries,
)


class Mitron(TCPOpticalSwitch, ABC):
    """
    | Represents Mitron optical switch
    | Kwargs available in the interface:

    :param str model: Model of the optical switch
    :param str host: Hostname or IP address of the optical switch
    :param int, optional port: Port number of the optical switch *(defaults to 4001)*
    :param int, optional timeout: Timeout for the optical switch *(defaults to 10)*
    :param int, optional buffer_size: Size of the buffer for the optical switch *(defaults to 128)*
    :param str, optional decode: Encoding for the optical switch *(defaults to 'utf-8')*
    :param int, optional retry: Number of retries for the optical switch *(defaults to 3)*
    :param int, optional interval: Interval between retries in seconds *(defaults to 1)*
    """

    def __init__(self, host, port=4001, **kwargs):
        super().__init__(host=host, port=port, **kwargs)
        self._response_errors = ["COMMAND_ERROR", "S_DATA_ERR2"]

    @property
    @abstractmethod
    def number_of_ports(self):
        """Number of ports on the optical switch"""
        pass

    @property
    @abstractmethod
    def device_name(self):
        pass

    def remove_connections(self, in_ports=None, out_ports=None, **kwargs):
        """Remove active connections by in_ports or out_ports

        :param list in_ports: List of input ports to remove connections by
        :param list out_ports: List of output ports to remove connections by
        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        :raises OpticalSwitchResponseError: Error in response or response invalid.
        :raises InvalidInput(OpticalSwitchError): Invalid input data.
        """
        if in_ports:
            self._remove_connections_by_inports(in_ports)
        if out_ports:
            self._remove_connections_by_outports(out_ports)

    def get_optical_switch_channels(self):
        """
        Get information which channels are set on which modules

        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        :raises OpticalSwitchResponseError: Error in response or response invalid.
        :return: dictionary with input port as key and output port as value
        """
        msg = self._build_get_optical_switch_channels_command()
        response = self._tcp_client.execute_with_retry(msg, self._retry, read=True)
        self._verify_response(response)
        return self._decode_get_optical_switch_channels_response(response)

    def set_optical_switch_channels(self, new_settings):
        """
        Set channels on modules

        :param dict new_settings: Dictionary with input port as key and output port as value
        :raises TooManyRetries(OpticalSwitchConnectionError): Request failed too many times.
        :raises OpticalSwitchResponseError: Error in response or response invalid.
        :raises InvalidInput(OpticalSwitchError): Invalid input data.
        """
        msg = self._build_set_optical_switch_channels_command(new_settings)
        response = self._tcp_client.execute_with_retry(msg, self._retry, read=True)
        self._verify_response(response)
        self._check_if_settings_changed(new_settings, self._retry)

    @staticmethod
    def _build_get_optical_switch_channels_command():
        return "<C01_[STA_?]>"

    def _build_set_optical_switch_channels_command(self, optical_connection_settings):
        """
        :param dict optical_connection_settings: delta changes with dict
        :return command for set switch channels
        """
        new_settings = self._normalize_connection_setting_dict(optical_connection_settings)
        self._verify_port_settings(new_settings)

        msg = self._build_get_optical_switch_channels_command()
        response = self._tcp_client.execute_with_retry(msg, self._retry, read=True)
        settings = self._decode_get_optical_switch_channels_response(response)

        settings.update(new_settings)

        output_ports = self._convert_dict_to_list(settings)
        output_ports_str = "_".join(output_ports)
        return f"<C01_[S_{output_ports_str}]>"

    @staticmethod
    def _normalize_connection_setting_dict(settings):
        """
        covert key and value as str with 2 digital position
        """
        return {str(input).zfill(2): str(output).zfill(2) for input, output in settings.items()}

    @staticmethod
    def _convert_dict_to_list(settings):
        return [settings[k] for k in sorted(settings.keys())]

    def _decode_get_optical_switch_channels_response(self, response):
        """
        decode the response to dict
        :param str response: original response
        example
        <C01_[MAX_16][S_02_01_03_04_05_06_07_08]>
        :return: dict of input:output
        example
        {'01': '02', '02': '01', '03': '03', '04': '04', '05': '05', '06': '06', '07': '07', '08': '08'}
        """
        pattern = re.compile(r"<C01_\[MAX_\d+\]\[S_(.*)\]>")
        result = pattern.findall(response)
        if not result:
            raise OpticalSwitchResponseError(f"Response for get optical switch channels is invalid: \n{response}")

        optical_connections = result[0].split("_")
        return {str(index + 1).zfill(2): output for index, output in enumerate(optical_connections)}

    def _verify_response(self, response):
        pattern = re.compile(r"<C\d*_\[(.*)\]>")  # e.g. <C01_[S_DATA_ERR2]>, <C00_[COMMAND_ERROR]>
        result = pattern.findall(response)
        if result:
            if result[0].upper() in self._response_errors:
                raise OpticalSwitchResponseError(f"Error in response: \n{response}")

    def _verify_port_settings(self, ports):
        if len(ports) > self.number_of_ports:
            raise InvalidInput(f"{self.device_name} only has {self.number_of_ports} output ports. Entered {ports}")

        for value in ports.values():
            if int(value) < 0 or int(value) > self.number_of_ports:
                raise InvalidInput(
                    f"""Output port value in {self.device_name}
                    must be in range <0;{self.number_of_ports}>. Entered {value}."""
                )

    def _remove_connections_by_inports(self, in_ports):
        settings = dict.fromkeys(in_ports, "00")
        self.set_optical_switch_channels(settings)

    def _remove_connections_by_outports(self, out_ports):
        connections = self.get_optical_switch_channels()
        in_ports_list = []
        normalized_out_ports = [str(port).zfill(2) for port in out_ports]
        for in_port, out_port in connections.items():
            if out_port in normalized_out_ports:
                in_ports_list.append(in_port)

        if len(in_ports_list) > 0:
            self._remove_connections_by_inports(in_ports_list)

    def _check_if_settings_changed(self, new_settings, retry):
        formated_new_settings = self._normalize_connection_setting_dict(new_settings)
        msg = self._build_get_optical_switch_channels_command()
        curr_tries = 0
        while retry > curr_tries:
            curr_tries += 1
            response = self._tcp_client.execute_with_retry(msg, self._retry, read=True)
            settings = self._decode_get_optical_switch_channels_response(response)
            if all(item in settings.items() for item in formated_new_settings.items()):
                return
            time.sleep(self._interval)
        raise TooManyRetries(f"Failed to check whether setting have changed in {retry} attempts")


class MitronOXC100032X32SM1356DD50LP(Mitron):
    MAX_PORTS = 32

    @property
    def number_of_ports(self):
        return self.MAX_PORTS

    @property
    def device_name(self):
        return "OXC1000-32X32-SM-1356-DD-50-LP"
